<section class="workspace-form-section"><h2 class="h6 mb-3">Informasi karyawan</h2><div class="border rounded-3 bg-light-subtle p-3"><div class="row g-3"><div class="col-sm-6"><small class="text-secondary d-block">Nama</small><strong>{{ $employee->full_name }}</strong></div><div class="col-sm-6"><small class="text-secondary d-block">NIP</small><strong>{{ $employee->employee_number }}</strong></div><div class="col-sm-6"><small class="text-secondary d-block">Jabatan</small><strong>{{ $employee->job_title ?: 'Belum diatur' }}</strong></div><div class="col-sm-6"><small class="text-secondary d-block">Perusahaan</small><strong>{{ $employee->company?->name ?: '-' }}</strong></div></div></div><div class="border rounded-3 bg-light-subtle p-3 mt-3"><small class="text-secondary d-block">Atasan</small>@if($employee->manager)<strong>{{ $employee->manager->full_name }}</strong><div class="small text-secondary">Persetujuan akan dikirim ke atasan langsung.</div>@else<div class="text-danger">Atasan langsung belum dikonfigurasi.</div>@endif</div><div class="border rounded-3 bg-light-subtle p-3 mt-3"><small class="text-secondary d-block">HR approver</small>@forelse($hrApprovers as $approver)<strong class="d-block">{{ $approver->user?->name ?: 'Pengguna HR' }}</strong><div class="small text-secondary">Akan memeriksa pengajuan setelah disetujui atasan.</div>@empty<div class="text-danger">Approver HR belum dikonfigurasi untuk perusahaan ini.</div>@endforelse</div></section>
</div></div></div>
<div class="card-footer bg-white d-flex justify-content-end gap-2 p-3"><a href="{{ route('workspace.hris.overtime') }}" class="btn btn-outline-secondary">Batal</a>@if(!$isEdit || $isDraft)<button type="submit" name="action" value="draft" class="btn btn-outline-secondary">Simpan draft</button>@endif<button type="submit" name="action" value="submit" class="btn btn-primary">{{ $isDraft ? 'Kirim pengajuan' : ($isEdit ? 'Kirim ulang revisi' : 'Kirim ke Atasan') }}</button></div>
</form>
<template id="overtime-entry-template"><div class="border rounded-3 p-3 mb-3 overtime-entry"><div class="d-flex justify-content-between align-items-center mb-3"><span class="badge rounded-pill bg-primary-subtle text-primary">Rincian baru</span><button type="button" class="btn btn-sm btn-outline-danger remove-overtime-entry">Hapus</button></div><div class="row g-3"><div class="col-md-4"><div class="workspace-floating-field"><input type="date" data-field="work_date" max="{{ now()->format('Y-m-d') }}" class="form-control" required><label class="form-label">Tanggal <span class="text-danger">*</span></label></div></div><div class="col-md-4"><div class="workspace-floating-field"><input type="text" data-field="start_time" class="form-control" placeholder="HH:mm" data-time-picker readonly required><label class="form-label">Mulai <span class="text-danger">*</span></label></div></div><div class="col-md-4"><div class="workspace-floating-field"><input type="text" data-field="end_time" class="form-control" placeholder="HH:mm" data-time-picker readonly required><label class="form-label">Selesai <span class="text-danger">*</span></label></div></div><div class="col-12"><div class="overtime-day-type"><div class="overtime-day-type-label">Jenis hari lembur</div><div class="overtime-day-type-options"><div class="overtime-day-type-option"><input type="radio" data-field="day_type" value="workday" checked><label>Hari Kerja</label></div><div class="overtime-day-type-option"><input type="radio" data-field="day_type" value="holiday"><label>Hari Libur</label></div></div></div></div><div class="col-12"><div class="workspace-floating-field"><textarea data-field="work_description" class="form-control" rows="3" maxlength="2000" required></textarea><label class="form-label">Uraian pekerjaan <span class="text-danger">*</span></label></div></div></div></div></template>
<script>
document.addEventListener('DOMContentLoaded', () => {
 const form=document.getElementById('overtime-form'),entries=document.getElementById('overtime-entries'),tpl=document.getElementById('overtime-entry-template');let next=entries.querySelectorAll('.overtime-entry').length;
 const sync=()=>entries.querySelectorAll('.remove-overtime-entry').forEach(b=>b.disabled=entries.querySelectorAll('.overtime-entry').length===1);
 const validationSummary=document.getElementById('client-validation-summary'),validationList=validationSummary.querySelector('[data-client-validation-list]');let firstInvalid=null;
 const clearClientValidation=()=>{form.querySelectorAll('.client-validation-invalid').forEach(element=>element.classList.remove('client-validation-invalid'));form.querySelectorAll('.client-validation-message').forEach(element=>element.remove());validationList.replaceChildren();validationSummary.hidden=true;firstInvalid=null};
 const addClientError=(field,message,container=field.closest('.workspace-floating-field')||field)=>{container.classList.add('client-validation-invalid');field.classList.add('client-validation-invalid');const error=document.createElement('div');error.className='client-validation-message';error.textContent=message;container.insertAdjacentElement('afterend',error);const item=document.createElement('li');item.textContent=message;validationList.appendChild(item);if(!firstInvalid)firstInvalid=field};
 const validDate=(value)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const [year,month,day]=value.split('-').map(Number);const date=new Date(year,month-1,day);return date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day};
 const validTime=(value)=>/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value);
 const validateClient=()=>{clearClientValidation();let valid=true;const fail=(field,message,container)=>{valid=false;addClientError(field,message,container)};const overtimeType=form.querySelector('[name="overtime_type"]:checked');if(!overtimeType)fail(form.querySelector('[name="overtime_type"]'),'Jenis lembur wajib dipilih.',form.querySelector('[name="overtime_type"]')?.closest('.row')||form);if(overtimeType?.value==='external_project'){const referenceType=form.querySelector('[name="work_reference_type"]:checked');if(!referenceType)fail(form.querySelector('[name="work_reference_type"]'),'Jenis referensi pekerjaan wajib dipilih.',form.querySelector('[name="work_reference_type"]')?.closest('.d-flex')||form);if(referenceType?.value==='project'&&!form.querySelector('[name="project_id"]')?.value)fail(form.querySelector('[name="project_id"]'), 'Project wajib dipilih.',form.querySelector('[name="overtime-project-field"]')||form);if(referenceType?.value==='opportunity'&&!form.querySelector('[name="opportunity_id"]')?.value)fail(form.querySelector('[name="opportunity_id"]'),'Opportunity wajib dipilih.',form.querySelector('[name="overtime-opportunity-field"]')||form)}const overtimeEntries=entries.querySelectorAll('.overtime-entry');if(!overtimeEntries.length){fail(entries,'Minimal satu rincian lembur wajib ditambahkan.',entries)}overtimeEntries.forEach((entry,index)=>{const date=entry.querySelector('[name$="[work_date]"]'),start=entry.querySelector('[name$="[start_time]"]'),end=entry.querySelector('[name$="[end_time]"]'),description=entry.querySelector('[name$="[work_description]"]'),dayType=entry.querySelector('[name$="[day_type]"]:checked');if(!date.value)fail(date,`Rincian ${index+1}: tanggal wajib diisi.`);else if(!validDate(date.value))fail(date,`Rincian ${index+1}: tanggal tidak valid.`);else if(date.value > '{{ now()->format('Y-m-d') }}')fail(date,`Rincian ${index+1}: tanggal tidak boleh setelah hari ini.`);if(!dayType)fail(entry.querySelector('[name$="[day_type]"]'),'Jenis hari lembur wajib dipilih.',entry.querySelector('.overtime-day-type'));if(!start.value||!validTime(start.value))fail(start,`Rincian ${index+1}: jam mulai harus berformat HH:mm.`);if(!end.value||!validTime(end.value))fail(end,`Rincian ${index+1}: jam selesai harus berformat HH:mm.`);if(validTime(start.value)&&validTime(end.value)&&end.value<=start.value)fail(end,`Rincian ${index+1}: jam selesai harus lebih besar dari jam mulai. Jika melewati tengah malam, buat rincian baru dengan tanggal berikutnya.`);if(!description.value.trim())fail(description,`Rincian ${index+1}: uraian pekerjaan wajib diisi.`);else if(description.value.trim().length>2000)fail(description,`Rincian ${index+1}: uraian pekerjaan maksimal 2.000 karakter.`)});if(!valid)return false;return true};
 form.addEventListener('submit',event=>{if(!validateClient()){event.preventDefault();validationSummary.hidden=false;validationSummary.scrollIntoView({behavior:'smooth',block:'center'});firstInvalid?.focus()}});
 const formatTime24=(field)=>{const digits=field.value.replace(/\D/g,'').slice(0,4);field.value=digits.length>2?`${digits.slice(0,2)}:${digits.slice(2)}`:digits};
 const timePicker=document.createElement('div');timePicker.className='workspace-time-picker-popup';timePicker.hidden=true;timePicker.innerHTML='<select data-time-hour aria-label="Jam" size="6"></select><select data-time-minute aria-label="Menit" size="6"></select><button type="button" class="btn btn-sm btn-outline-secondary" data-time-close>Tutup</button>';document.body.appendChild(timePicker);
 const hourSelect=timePicker.querySelector('[data-time-hour]'),minuteSelect=timePicker.querySelector('[data-time-minute]');
 for(let hour=0;hour<24;hour++){const option=document.createElement('option');option.value=String(hour).padStart(2,'0');option.textContent=option.value;hourSelect.appendChild(option)}
 for(let minute=0;minute<60;minute++){const option=document.createElement('option');option.value=String(minute).padStart(2,'0');option.textContent=option.value;minuteSelect.appendChild(option)}
 let activeTimeField=null;
 const closeTimePicker=()=>{timePicker.hidden=true;activeTimeField=null};
 const updateTimeField=()=>{if(activeTimeField)activeTimeField.value=`${hourSelect.value}:${minuteSelect.value}`};
 const openTimePicker=(field)=>{activeTimeField=field;const [hour='00',minute='00']=(field.value||'00:00').split(':');hourSelect.value=hour;minuteSelect.value=minute;const rect=field.getBoundingClientRect();timePicker.hidden=false;const top=rect.bottom+4+132+48>window.innerHeight?rect.top-184:rect.bottom+4;timePicker.style.top=`${Math.max(8,top)}px`;timePicker.style.left=`${Math.min(Math.max(8,rect.left),window.innerWidth-timePicker.offsetWidth-8)}px`};
 hourSelect.addEventListener('change',updateTimeField);minuteSelect.addEventListener('change',updateTimeField);timePicker.querySelector('[data-time-close]').addEventListener('click',closeTimePicker);
 document.getElementById('overtime-form').addEventListener('focusin',event=>{if(event.target.matches('[data-time-picker]'))openTimePicker(event.target)});
 document.addEventListener('mousedown',event=>{if(activeTimeField&&!event.target.closest('.workspace-time-picker-popup')&&event.target!==activeTimeField)closeTimePicker()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeTimePicker()});
 document.getElementById('overtime-form').addEventListener('input',event=>{if(event.target.matches('[data-time-24]'))formatTime24(event.target)});
 document.getElementById('add-overtime-entry').addEventListener('click',()=>{const n=tpl.content.cloneNode(true);n.querySelectorAll('[data-field]').forEach(f=>{const suffix=f.type==='radio'?`-${f.value}`:'';const id=`entry-${next}-${f.dataset.field}${suffix}`;f.id=id;f.name=`entries[${next}][${f.dataset.field}]`;f.nextElementSibling?.setAttribute('for',id)});entries.appendChild(n);next++;sync()});
 entries.addEventListener('click',e=>{const b=e.target.closest('.remove-overtime-entry');if(b&&entries.querySelectorAll('.overtime-entry').length>1){b.closest('.overtime-entry').remove();sync()}});
 const referenceField=document.getElementById('overtime-reference-field'),projectField=document.getElementById('overtime-project-field'),opportunityField=document.getElementById('overtime-opportunity-field'),project=document.getElementById('overtime-project'),opportunity=document.getElementById('overtime-opportunity'),summary=document.getElementById('overtime-reference-summary');
 const closePickers=()=>document.querySelectorAll('.reference-picker-menu').forEach(menu=>{menu.classList.remove('is-open');menu.hidden=true;menu.style.removeProperty('top');menu.style.removeProperty('left');menu.style.removeProperty('width')});
 document.querySelectorAll('[data-reference-picker]').forEach(picker=>{const toggle=picker.querySelector('[data-bs-toggle="dropdown"]'),menu=picker.querySelector('.dropdown-menu');if(!toggle||!menu)return;toggle.removeAttribute('data-bs-toggle');toggle.removeAttribute('data-bs-auto-close');toggle.setAttribute('aria-expanded','false');menu.classList.add('reference-picker-menu');menu.dataset.referenceKind=picker.dataset.referencePicker;menu.hidden=true;toggle.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();const open=menu.classList.contains('is-open');closePickers();if(!open){const rect=toggle.getBoundingClientRect();const viewportWidth=document.documentElement.clientWidth;const width=Math.min(Math.max(rect.width,620),Math.max(280,viewportWidth-32));if(menu.parentElement!==document.body)document.body.appendChild(menu);menu.style.setProperty('min-width','0','important');menu.style.setProperty('position','fixed','important');menu.style.setProperty('top',`${Math.min(rect.bottom+4,window.innerHeight-24)}px`,'important');menu.style.setProperty('left',`${Math.max(16,Math.min(rect.left,viewportWidth-width-16))}px`,'important');menu.style.setProperty('width',`${width}px`,'important');menu.style.maxHeight=`${Math.max(180,window.innerHeight-rect.bottom-32)}px`;menu.hidden=false;menu.classList.add('is-open');toggle.setAttribute('aria-expanded','true')}})});
 document.addEventListener('click',event=>{if(!event.target.closest('[data-reference-picker]')&&!event.target.closest('.reference-picker-menu'))closePickers()});
 const renderSummary=(choice)=>{if(!choice){summary.hidden=true;return}summary.hidden=false;summary.querySelector('[data-reference-summary-name]').textContent=choice.dataset.referenceName;const badges=summary.querySelector('[data-reference-summary-badges]');badges.replaceChildren();const classification=choice.dataset.referenceClassification;if(classification){const classificationBadge=document.createElement('span');classificationBadge.className='badge rounded-pill '+({Sales:'text-bg-success',Dibatalkan:'text-bg-danger',Lost:'text-bg-warning text-dark',Diabaikan:'text-bg-secondary',Project:'text-bg-primary'}[classification]||'text-bg-primary');classificationBadge.textContent=classification;badges.appendChild(classificationBadge)}if(choice.dataset.referenceStage){const stageBadge=document.createElement('span');stageBadge.className='badge rounded-pill text-bg-light';stageBadge.textContent='Stage: '+choice.dataset.referenceStage;badges.appendChild(stageBadge)}if(choice.dataset.referenceClosing){const closingBadge=document.createElement('span');closingBadge.className='badge rounded-pill text-bg-secondary';closingBadge.textContent='Closing: '+choice.dataset.referenceClosing;badges.appendChild(closingBadge)}summary.querySelector('[data-reference-summary-client]').textContent='Client: '+choice.dataset.referenceClient;summary.querySelector('[data-reference-summary-contact]').textContent='Kontak: '+choice.dataset.referenceContact};
 const selectChoice=(choice)=>{const kind=choice.dataset.referenceKind;const input=kind==='project'?project:opportunity;const picker=document.querySelector('[data-reference-picker="'+kind+'"]');if(!input||!picker)return;input.value=choice.dataset.referenceValue;picker.querySelector('[data-reference-label]').textContent=choice.dataset.referenceName;document.querySelectorAll('[data-reference-choice][data-reference-kind="'+kind+'"]').forEach(button=>{button.classList.toggle('active',button===choice);button.closest('[data-reference-row]')?.classList.toggle('is-selected',button===choice)});renderSummary(choice);closePickers()};
 document.getElementById('overtime-form').addEventListener('click',event=>{const choice=event.target.closest('[data-reference-choice]');if(!choice)return;event.preventDefault();event.stopPropagation();selectChoice(choice)});
 document.querySelectorAll('[data-reference-row]').forEach(row=>row.addEventListener('click',event=>{if(event.target.closest('button'))return;const choice=row.querySelector('[data-reference-choice]');if(choice)selectChoice(choice)}));
 document.querySelectorAll('[data-reference-search]').forEach(search=>search.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();document.querySelectorAll('[data-reference-row][data-reference-kind="'+search.dataset.referenceSearch+'"]').forEach(row=>{row.hidden=term!==''&&!row.dataset.referenceSearchText.includes(term)})}));
 const restoreChoice=()=>{const reference=document.querySelector('[name="work_reference_type"]:checked')?.value;const value=reference==='project'?project.value:reference==='opportunity'?opportunity.value:'';const choice=[...document.querySelectorAll('[data-reference-choice][data-reference-kind="'+reference+'"]')].find(button=>button.dataset.referenceValue===value);if(choice){document.querySelector('[data-reference-picker="'+reference+'"] [data-reference-label]').textContent=choice.dataset.referenceName;choice.classList.add('active')}renderSummary(choice)};
 const opportunityOwners=JSON.parse(document.getElementById('overtime-opportunity-metadata')?.textContent||'{}');
 const normalizeReferencePicker=(field,kind)=>{const row=field?.querySelector(':scope > .row');if(!row)return;const primary=row.querySelector(':scope > .col-md-5');const search=row.querySelector(':scope > .col-md-7')||primary?.querySelector(':scope > .col-md-7');const picker=primary?.querySelector('[data-reference-picker]');const menu=picker?.querySelector('.dropdown-menu');if(search&&menu){const searchBox=search.querySelector('.input-group');if(searchBox){searchBox.classList.add('reference-picker-search');menu.prepend(searchBox)}search.remove()}const help=row.querySelector(':scope > .form-text');if(help)field.appendChild(help);if(menu){const table=menu.querySelector('table');const head=table?.tHead?.rows[0];if(kind==='project'&&head&&!head.querySelector('[data-contact-column]')){const th=document.createElement('th');th.dataset.contactColumn='';th.textContent='Kontak';head.insertBefore(th,head.lastElementChild);table.querySelectorAll('tbody tr[data-reference-row]').forEach(tr=>{const td=document.createElement('td');td.textContent=tr.querySelector('[data-reference-choice]')?.dataset.referenceContact||'—';tr.insertBefore(td,tr.lastElementChild)})}if(kind==='opportunity'&&head&&!head.querySelector('[data-owner-column]')){const th=document.createElement('th');th.dataset.ownerColumn='';th.textContent='Perusahaan pemilik';head.insertBefore(th,head.children[1]||null);table.querySelectorAll('tbody tr[data-reference-row]').forEach(tr=>{const choice=tr.querySelector('[data-reference-choice]');const td=document.createElement('td');td.textContent=opportunityOwners[choice?.dataset.referenceValue]||'—';tr.insertBefore(td,tr.children[1]||null)})}}row.classList.add('reference-picker-row');};
 if(opportunityField&&referenceField&&opportunityField.parentElement!==referenceField)referenceField.appendChild(opportunityField);
 normalizeReferencePicker(projectField,'project');normalizeReferencePicker(opportunityField,'opportunity');
 const reorderOpportunityColumns=()=>{const table=document.querySelector('[data-reference-picker="opportunity"] table');const head=table?.tHead?.rows[0];if(!table||!head)return;const order=[0,1,3,2,4,5];const move=(parent)=>{const cells=[...parent.children];order.forEach(index=>{if(cells[index])parent.appendChild(cells[index])})};move(head);table.querySelectorAll('tbody tr[data-reference-row]').forEach(move)};reorderOpportunityColumns();
 const locationField=document.getElementById('overtime-location')?.closest('.workspace-floating-field');if(locationField&&referenceField?.parentElement&&locationField.parentElement!==referenceField.parentElement)referenceField.after(locationField);
 const setVisible=(element,visible)=>{if(!element)return;if(visible){element.removeAttribute('hidden');element.style.setProperty('display','block','important')}else{element.setAttribute('hidden','hidden');element.style.setProperty('display','none','important')}};
 const syncReference=()=>{const ext=document.querySelector('[name="overtime_type"]:checked')?.value==='external_project';const reference=document.querySelector('[name="work_reference_type"]:checked')?.value||'none';setVisible(referenceField,ext);setVisible(projectField,ext&&reference==='project');setVisible(opportunityField,ext&&reference==='opportunity');project.disabled=!ext||reference!=='project';opportunity.disabled=!ext||reference!=='opportunity';if(!ext||reference!=='project')project.value='';if(!ext||reference!=='opportunity')opportunity.value='';restoreChoice()};
 document.querySelectorAll('[name="overtime_type"], [name="work_reference_type"]').forEach(r=>r.addEventListener('change',syncReference));document.getElementById('overtime-form').addEventListener('change',event=>{if(event.target.matches('[name="overtime_type"],[name="work_reference_type"]'))syncReference()});syncReference();window.setTimeout(syncReference,0);sync();
});
</script>
@endsection
